import '../../domain/entities/user_profile.dart';import '../../domain/repositories/profile_repository.dart';import '../datasources/profile_remote_data_source.dart';import '../models/user_profile_model.dart';class FirestoreProfileRepository implements ProfileRepository{final ProfileRemoteDataSource source;FirestoreProfileRepository(this.source);Future<UserProfile> getProfile()=>source.getProfile();Future<UserProfile> updateProfile({required UserProfile profile})=>source.updateProfile(UserProfileModel(uid:profile.uid,displayName:profile.displayName,email:profile.email,createdAt:profile.createdAt,updatedAt:profile.updatedAt));}
